-- Generated by supabase/seed/make_seed_sql.py. Do not edit by hand.
-- 120 evaluations, 4634 observations, 120 models, 30 manufacturers.
--
-- EVERY ROW IS SYNTHETIC. The no_certificate_for_synthetic constraint
-- makes it impossible to issue a certificate against any of it.
