begin;

-- The guard triggers exist to stop exactly what a bulk load does:
-- writing observations into non-draft evaluations and setting status
-- without a JWT role. Disable them for the load only.
alter table evaluation  disable trigger evaluation_guard;
alter table observation disable trigger observation_guard;
alter table evaluation  disable trigger audit_evaluation;
alter table observation disable trigger audit_observation;

