-- observations --------------------------------------------------------
-- No temporary table: the Supabase SQL Editor commits statement by
-- statement, so a temp table created with ON COMMIT DROP is destroyed
-- the moment it is created and the next statement cannot see it.
-- A VALUES list joined straight to evaluation needs no staging at all,
-- and works the same in the editor and in psql.

insert into observation (
  evaluation_id, test_code, variant, sequence_no,
  load_g, indication_g, delta_load_g, direction, position,
  elapsed_minutes, weighing_no,
  indication_without_g, indication_with_g,
  significant_fault_detected, severity)
