on conflict do nothing;

-- restore the guards --------------------------------------------------
alter table evaluation  enable trigger evaluation_guard;
alter table observation enable trigger observation_guard;
alter table evaluation  enable trigger audit_evaluation;
alter table observation enable trigger audit_observation;

commit;

-- verification ---------------------------------------------------------
select 'evaluations' as what, count(*) from evaluation
union all select 'observations', count(*) from observation
union all select 'models',       count(*) from instrument_model
union all select 'manufacturers',count(*) from manufacturer;

select status, count(*) from evaluation group by status order by 2 desc;
select verdict, count(*) from evaluation group by verdict;
select * from v_dashboard_counts order by total desc;

-- must return zero rows: no synthetic row may carry a certificate
select ref, status, certificate_no, gazette_date from evaluation
where is_synthetic and (certificate_no is not null or gazette_date is not null);
